// One webhook call = one message = one Langfuse trace.
//
// sessionId and msg_id play different roles and must not be conflated:
//   sessionId -> conversation context. It keys the chat memory, and the proxy
//                maps metadata.session_id onto the Langfuse sessionId, so every
//                trace of the conversation is grouped under one Session.
//   msg_id    -> this single request. It identifies and correlates one webhook
//                call, so it goes on the trace as metadata and as a tag you can
//                filter on. A new one arrives with every message.

const { ChatPromptTemplate, MessagesPlaceholder } = require('@langchain/core/prompts');
const { StringOutputParser } = require('@langchain/core/output_parsers');

const body = $input.first().json.body || $input.first().json;

// Minted here when absent, and only here: sessionId keys the conversation and
// its memory, msg_id identifies this one message. Both are echoed back so the
// caller can reuse the sessionId on the next turn.
const sessionId = body.sessionId || `SESSION-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
const msgId     = body.msg_id    || `MSG-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
const question  = body.chatInput || (body.message && body.message.payload) || '';

const llm    = await this.getInputConnectionData('ai_languageModel', 0);
const memory = await this.getInputConnectionData('ai_memory', 0);

// Conversation context belongs to the session, so it is loaded and saved under
// sessionId — never under msg_id, which is unique per message and would make
// every turn start from an empty history.
const history = memory ? (await memory.loadMemoryVariables({})).chat_history || [] : [];

const prompt = ChatPromptTemplate.fromMessages([
  ['system', 'You are a concise assistant. Answer in one sentence.'],
  new MessagesPlaceholder('chat_history'),
  ['human', '{question}'],
]);

const chain = prompt.pipe(llm).pipe(new StringOutputParser()).withConfig({
  runName: `chat ${msgId}`,
  tags: ['node:crm', `msg:${msgId}`],
  metadata: {
    node: 'crm',
    session_id: sessionId,
    msg_id: msgId,
    user_id: body.user_id || 'anonymous',
    route: body.route || null,
    action: body.action || null,
    workflow_name: 'Chat Webhook',
  },
});

const output = await chain.invoke({ question, chat_history: history });

if (memory) await memory.saveContext({ input: question }, { output });

return [{ json: { sessionId, msg_id: msgId, chatInput: question, output } }];
